const { chromium } = require('/Users/yuvalt/personal/visual-renderer/bench/versus-browser/tooling/node_modules/playwright');
(async () => {
  const b = await chromium.launch();
  const sizes = {portrait:[1080,1350], wide:[1200,1000], sky:[300,600]};
  for (const [n,[w,h]] of Object.entries(sizes)) {
    const p = await b.newPage({viewportSize:{width:w,height:h}});
    await p.goto('file://' + process.argv[2] + '/' + n + '.html');
    await p.waitForTimeout(400);
    const r = await p.evaluate(() => {
      const out = {};
      const sel = ['.headline','.photoband','.candidates','.cta','.steps','.footer'];
      for (const s of sel) { const e=document.querySelector(s); const b=e.getBoundingClientRect();
        out[s]=[Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)]; }
      out.scrollH = document.documentElement.scrollHeight;
      out.scrollW = document.documentElement.scrollWidth;
      // overflow check: any text node wider than its box?
      out.over = [];
      document.querySelectorAll('.name,.role,.label,.txt,.footer,.headline').forEach(e=>{
        if (e.scrollWidth > e.clientWidth+1 || e.scrollHeight > e.clientHeight+1)
          out.over.push([e.className, e.scrollWidth, e.clientWidth, e.scrollHeight, e.clientHeight, e.textContent.slice(0,25)]);
      });
      return out;
    });
    console.log(n, JSON.stringify(r,null,0));
    await p.close();
  }
  await b.close();
})();
EOF
